From 8de4d0f3e75e03e361e3b95b1f685efc3efe8b20 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 20:22:58 +0100
Subject: [PATCH] ApplicationLauncherJob: add RunOnDiscreteGpu run flag

Launchers could only start an app on the discrete GPU when its desktop
file sets PrefersNonDefaultGPU, so there was no way to do it just once.
The new flag and hasDiscreteGpu() let them offer a one-off action.

BUG: 392523
---
 src/gui/applicationlauncherjob.cpp |  6 ++++++
 src/gui/applicationlauncherjob.h   | 10 ++++++++++
 src/gui/dbusactivationrunner.cpp   |  4 ++++
 src/gui/kprocessrunner.cpp         |  2 +-
 4 files changed, 21 insertions(+), 1 deletion(-)

diff --git a/src/gui/applicationlauncherjob.cpp b/src/gui/applicationlauncherjob.cpp
index c369b2c53..0874f56d0 100644
--- a/src/gui/applicationlauncherjob.cpp
+++ b/src/gui/applicationlauncherjob.cpp
@@ -7,6 +7,7 @@

 #include "applicationlauncherjob.h"
 #include "../core/global.h"
+#include "gpudetection_p.h"
 #include "jobuidelegatefactory.h"
 #include "kiogui_debug.h"
 #include "kprocessrunner_p.h"
@@ -109,6 +110,11 @@ void KIO::ApplicationLauncherJob::setRunFlags(RunFlags runFlags)
     d->m_runFlags = runFlags;
 }

+bool KIO::ApplicationLauncherJob::hasDiscreteGpu()
+{
+    return KIO::hasDiscreteGpu();
+}
+
 void KIO::ApplicationLauncherJob::setSuggestedFileName(const QString &suggestedFileName)
 {
     d->m_suggestedFileName = suggestedFileName;
diff --git a/src/gui/applicationlauncherjob.h b/src/gui/applicationlauncherjob.h
index 3a479f1c9..b9633cf8a 100644
--- a/src/gui/applicationlauncherjob.h
+++ b/src/gui/applicationlauncherjob.h
@@ -112,9 +112,12 @@ public:

     /*!
      * \value DeleteTemporaryFiles The URLs passed to the service will be deleted when it exits (if the URLs are local files)
+     * \value RunOnDiscreteGpu The application is started on the discrete GPU, as if its desktop file had PrefersNonDefaultGPU=true.
+     *        Has no effect if there is no discrete GPU, see hasDiscreteGpu(). Since 6.33
      */
     enum RunFlag {
         DeleteTemporaryFiles = 0x1,
+        RunOnDiscreteGpu = 0x2,
     };
     Q_DECLARE_FLAGS(RunFlags, RunFlag)

@@ -125,6 +128,13 @@ public:
      */
     void setRunFlags(RunFlags runFlags);

+    /*!
+     * Returns true if the system has a discrete GPU that applications can be started on, see RunOnDiscreteGpu.
+     *
+     * \since 6.33
+     */
+    static bool hasDiscreteGpu();
+
     /*!
      * Sets the file name to use in the case of downloading the file to a tempfile
      * in order to give to a non-URL-aware application.
diff --git a/src/gui/dbusactivationrunner.cpp b/src/gui/dbusactivationrunner.cpp
index 6b90c073c..ef5e96edb 100644
--- a/src/gui/dbusactivationrunner.cpp
+++ b/src/gui/dbusactivationrunner.cpp
@@ -34,6 +34,10 @@ bool DBusActivationRunner::activationPossible(const KService::Ptr service, KIO::
             qCDebug(KIO_GUI) << "Cannot activate" << service->desktopEntryName() << "because DeleteTemporaryFiles is set";
             return false;
         }
+        if (flags & KIO::ApplicationLauncherJob::RunOnDiscreteGpu) {
+            qCDebug(KIO_GUI) << "Cannot activate" << service->desktopEntryName() << "because RunOnDiscreteGpu is set";
+            return false;
+        }
         return true;
     }
     return false;
diff --git a/src/gui/kprocessrunner.cpp b/src/gui/kprocessrunner.cpp
index bc9cd63ea..341c1c132 100644
--- a/src/gui/kprocessrunner.cpp
+++ b/src/gui/kprocessrunner.cpp
@@ -142,7 +142,7 @@ KProcessRunner *KProcessRunner::fromApplication(const KService::Ptr &service,
     *instance->m_process << args;

 #ifndef Q_OS_ANDROID
-    if (service->runOnDiscreteGpu()) {
+    if (service->runOnDiscreteGpu() || (flags & KIO::ApplicationLauncherJob::RunOnDiscreteGpu)) {
         modifyEnv(*instance->m_process, KIO::discreteGpuEnvironment());
     }
 #endif
-- 
