From 61c2bfbf0f386905a4fec04fddd0e318a6913053 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 20:22:58 +0100
Subject: [PATCH] applets/taskmanager: offer to run apps on the dedicated
 graphics card

Starting an app on the dedicated GPU needed editing its desktop entry
first. On systems with one, the context menu of launchers and of tasks
that can open a new window now has an action to do it just this once.

BUG: 392523
---
 applets/taskmanager/backend.cpp         | 43 +++++++++++++++++++++++++
 applets/taskmanager/backend.h           |  3 ++
 applets/taskmanager/qml/ContextMenu.qml | 12 +++++++
 3 files changed, 58 insertions(+)

diff --git a/applets/taskmanager/backend.cpp b/applets/taskmanager/backend.cpp
index 1005d2a981..1ec8831fc6 100644
--- a/applets/taskmanager/backend.cpp
+++ b/applets/taskmanager/backend.cpp
@@ -23,6 +23,7 @@

 #include <KApplicationTrader>
 #include <KIO/ApplicationLauncherJob>
+#include <kio_version.h>

 #include <QAction>
 #include <QActionGroup>
@@ -541,6 +542,48 @@ bool Backend::isApplication(const QUrl &url) const
     return desktopFile.hasApplicationType();
 }

+bool Backend::canRunOnDiscreteGpu(const QUrl &launcherUrl) const
+{
+#if KIO_VERSION >= QT_VERSION_CHECK(6, 33, 0)
+    const QUrl desktopEntryUrl = tryDecodeApplicationsUrl(launcherUrl);
+
+    if (!isApplication(desktopEntryUrl) || !KIO::ApplicationLauncherJob::hasDiscreteGpu()) {
+        return false;
+    }
+
+    const KService::Ptr service = KService::serviceByDesktopPath(desktopEntryUrl.toLocalFile());
+    return service && !service->runOnDiscreteGpu();
+#else
+    Q_UNUSED(launcherUrl)
+    return false;
+#endif
+}
+
+void Backend::runOnDiscreteGpu(const QUrl &launcherUrl) const
+{
+#if KIO_VERSION >= QT_VERSION_CHECK(6, 33, 0)
+    const QUrl desktopEntryUrl = tryDecodeApplicationsUrl(launcherUrl);
+
+    if (!isApplication(desktopEntryUrl)) {
+        return;
+    }
+
+    const KService::Ptr service = KService::serviceByDesktopPath(desktopEntryUrl.toLocalFile());
+    if (!service) {
+        return;
+    }
+
+    auto *job = new KIO::ApplicationLauncherJob(service);
+    auto *delegate = new KNotificationJobUiDelegate;
+    delegate->setAutoErrorHandlingEnabled(true);
+    job->setUiDelegate(delegate);
+    job->setRunFlags(KIO::ApplicationLauncherJob::RunOnDiscreteGpu);
+    job->start();
+#else
+    Q_UNUSED(launcherUrl)
+#endif
+}
+
 qint64 Backend::parentPid(qint64 pid) const
 {
     KSysGuard::Processes procs;
diff --git a/applets/taskmanager/backend.h b/applets/taskmanager/backend.h
index f95faee70b..86e3caa1fd 100644
--- a/applets/taskmanager/backend.h
+++ b/applets/taskmanager/backend.h
@@ -63,6 +63,9 @@ public:

     Q_INVOKABLE bool isApplication(const QUrl &url) const;

+    Q_INVOKABLE bool canRunOnDiscreteGpu(const QUrl &launcherUrl) const;
+    Q_INVOKABLE void runOnDiscreteGpu(const QUrl &launcherUrl) const;
+
     Q_INVOKABLE qint64 parentPid(qint64 pid) const;

     Q_INVOKABLE static QUrl tryDecodeApplicationsUrl(const QUrl &launcherUrl);
diff --git a/applets/taskmanager/qml/ContextMenu.qml b/applets/taskmanager/qml/ContextMenu.qml
index fe837049fc..fa0c3bcd95 100644
--- a/applets/taskmanager/qml/ContextMenu.qml
+++ b/applets/taskmanager/qml/ContextMenu.qml
@@ -280,6 +280,18 @@ PlasmaExtras.Menu {
         onClicked: tasksModel.requestNewInstance(menu.modelIndex)
     }

+    PlasmaExtras.MenuItem {
+        id: runOnDiscreteGpuItem
+        visible: (menu.get(TaskManager.AbstractTasksModel.IsLauncher) || startNewInstanceItem.visible)
+            && menu.backend.canRunOnDiscreteGpu(menu.get(TaskManager.AbstractTasksModel.LauncherUrlWithoutIcon))
+        text: menu.get(TaskManager.AbstractTasksModel.IsLauncher)
+            ? i18nc("@action:inmenu", "Run Using Dedicated Graphics Card")
+            : i18nc("@action:inmenu", "Open New Window Using Dedicated Graphics Card")
+        icon: "show-gpu-effects"
+
+        onClicked: menu.backend.runOnDiscreteGpu(menu.get(TaskManager.AbstractTasksModel.LauncherUrlWithoutIcon))
+    }
+
     PlasmaExtras.MenuItem {
         id: virtualDesktopsMenuItem

-- 
