From 4eebcf3f9779f470eef3fe56259df900b117dbc1 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 20:22:58 +0100
Subject: [PATCH] applets/kicker: add "Run Using Dedicated Graphics Card"
 action

Starting an app on the dedicated GPU needed editing its desktop entry
first. On systems with one, the app context menu in Kickoff, Kicker and
search results now has an action that runs it there just this once.

BUG: 392523
---
 applets/kicker/actionlist.cpp         | 36 +++++++++++++++++++++++++++
 applets/kicker/actionlist.h           |  3 +++
 applets/kicker/appentry.cpp           |  4 +++
 applets/kicker/recentusagemodel.cpp   |  5 +++-
 applets/kicker/runnermatchesmodel.cpp |  4 ++-
 5 files changed, 50 insertions(+), 2 deletions(-)

diff --git a/applets/kicker/actionlist.cpp b/applets/kicker/actionlist.cpp
index db486ea5e2..9d5df3e2da 100644
--- a/applets/kicker/actionlist.cpp
+++ b/applets/kicker/actionlist.cpp
@@ -23,6 +23,7 @@
 #include <KPropertiesDialog>
 #include <KProtocolInfo>
 #include <KRecentDocument>
+#include <kio_version.h>

 #include <KIO/DesktopExecParser>
 #include <PlasmaActivities/Stats/Cleaning>
@@ -407,6 +408,41 @@ bool handleEditApplicationAction(const QString &actionId, const KService::Ptr &s
     return false;
 }

+QVariantList dedicatedGpuActions(const KService::Ptr &service)
+{
+    QVariantList actionList;
+
+#if KIO_VERSION >= QT_VERSION_CHECK(6, 33, 0)
+    if (service && service->isApplication() && !service->runOnDiscreteGpu() && KIO::ApplicationLauncherJob::hasDiscreteGpu()) {
+        actionList << Kicker::createActionItem(i18n("Run Using Dedicated Graphics Card"),
+                                               QStringLiteral("show-gpu-effects"),
+                                               QStringLiteral("_kicker_runOnDiscreteGpu"));
+    }
+#else
+    Q_UNUSED(service)
+#endif
+
+    return actionList;
+}
+
+bool handleDedicatedGpuAction(const QString &actionId, const KService::Ptr &service)
+{
+#if KIO_VERSION >= QT_VERSION_CHECK(6, 33, 0)
+    if (service && service->isApplication() && actionId == QLatin1String("_kicker_runOnDiscreteGpu")) {
+        auto *job = new KIO::ApplicationLauncherJob(service);
+        job->setRunFlags(KIO::ApplicationLauncherJob::RunOnDiscreteGpu);
+        job->setUiDelegate(new KNotificationJobUiDelegate(KJobUiDelegate::AutoHandlingEnabled));
+        job->start();
+        return true;
+    }
+#else
+    Q_UNUSED(actionId)
+    Q_UNUSED(service)
+#endif
+
+    return false;
+}
+
 #ifdef HAVE_APPSTREAMQT
 Q_GLOBAL_STATIC(AppStream::Pool, appstreamPool)
 #endif
diff --git a/applets/kicker/actionlist.h b/applets/kicker/actionlist.h
index c7825a692e..da5e2d0698 100644
--- a/applets/kicker/actionlist.h
+++ b/applets/kicker/actionlist.h
@@ -58,6 +58,9 @@ bool handleRecentDocumentAction(KService::Ptr service, const QString &actionId,
 QVariantList editApplicationAction(const KService::Ptr &service);
 bool handleEditApplicationAction(const QString &actionId, const KService::Ptr &service);

+QVariantList dedicatedGpuActions(const KService::Ptr &service);
+bool handleDedicatedGpuAction(const QString &actionId, const KService::Ptr &service);
+
 QVariantList appstreamActions(const KService::Ptr &service);
 bool handleAppstreamActions(const QString &actionId, const KService::Ptr &service);

diff --git a/applets/kicker/appentry.cpp b/applets/kicker/appentry.cpp
index e3c1d4aa5f..4b38ec62cc 100644
--- a/applets/kicker/appentry.cpp
+++ b/applets/kicker/appentry.cpp
@@ -357,6 +357,7 @@ QVariantList AppEntry::actions() const
     QVariantList actionList;

     if (!m_serviceAction) {
+        actionList << Kicker::dedicatedGpuActions(m_service);
         actionList << Kicker::jumpListActions(m_service);
         if (!actionList.isEmpty()) {
             actionList << Kicker::createSeparatorActionItem();
@@ -440,6 +441,9 @@ bool AppEntry::run(const QString &actionId, const QVariant &argument)
         return true;
     } else if (Kicker::handleAppstreamActions(actionId, m_service)) {
         return true;
+    } else if (Kicker::handleDedicatedGpuAction(actionId, m_service)) {
+        KActivities::ResourceInstance::notifyAccessed(QUrl(QString(u"applications:" + m_service->storageId())), QStringLiteral("org.kde.plasma.kicker"));
+        return true;
     } else if (actionId == QLatin1String("_kicker_jumpListAction")) {
         auto *job = new KIO::ApplicationLauncherJob(argument.value<KServiceAction>());
         job->setUiDelegate(new KNotificationJobUiDelegate(KJobUiDelegate::AutoHandlingEnabled));
diff --git a/applets/kicker/recentusagemodel.cpp b/applets/kicker/recentusagemodel.cpp
index e28299e899..c3593c0056 100644
--- a/applets/kicker/recentusagemodel.cpp
+++ b/applets/kicker/recentusagemodel.cpp
@@ -233,7 +233,7 @@ QVariant RecentUsageModel::appData(const QString &resource, int role) const
     } else if (role == Kicker::ActionListRole) {
         QVariantList actionList;

-        const QVariantList &jumpList = Kicker::jumpListActions(service);
+        const QVariantList jumpList = Kicker::dedicatedGpuActions(service) + Kicker::jumpListActions(service);
         if (!jumpList.isEmpty()) {
             actionList << jumpList;
         }
@@ -472,6 +472,9 @@ bool RecentUsageModel::trigger(int row, const QString &actionId, const QVariant
             KService::Ptr service = KService::serviceByStorageId(storageId);

             if (service) {
+                if (Kicker::handleDedicatedGpuAction(actionId, service)) {
+                    return true;
+                }
                 return Kicker::handleRecentDocumentAction(service, actionId, argument);
             }
         } else {
diff --git a/applets/kicker/runnermatchesmodel.cpp b/applets/kicker/runnermatchesmodel.cpp
index 8c1ea5790c..fdb7733465 100644
--- a/applets/kicker/runnermatchesmodel.cpp
+++ b/applets/kicker/runnermatchesmodel.cpp
@@ -169,7 +169,7 @@ QVariant RunnerMatchesModel::data(const QModelIndex &index, int role) const
                 actionList << Kicker::createSeparatorActionItem();
             }

-            const QVariantList &jumpListActions = Kicker::jumpListActions(service);
+            const QVariantList jumpListActions = Kicker::dedicatedGpuActions(service) + Kicker::jumpListActions(service);
             if (!jumpListActions.isEmpty()) {
                 actionList << jumpListActions << Kicker::createSeparatorActionItem();
             }
@@ -257,6 +257,8 @@ bool RunnerMatchesModel::trigger(int row, const QString &actionId, const QVarian
         return true;
     } else if (Kicker::handleAppstreamActions(actionId, service)) {
         return true;
+    } else if (Kicker::handleDedicatedGpuAction(actionId, service)) {
+        return true;
     } else if (actionId == QLatin1String("_kicker_jumpListAction")) {
         auto job = new KIO::ApplicationLauncherJob(argument.value<KServiceAction>());
         job->setUiDelegate(new KNotificationJobUiDelegate(KJobUiDelegate::AutoHandlingEnabled));
